import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Сервис кондиционеров: CRM заявок, выездов мастеров и договоров обслуживания"}>
      <p>{"Мы в Краснодаре ставим и обслуживаем кондиционеры: частные квартиры, магазины и небольшие офисы. Три диспетчера, девять мастеров, весной и летом заявок в три раза больше. Нужна CRM. Заявка с сайта или по телефону: клиент, адрес, что случилось или что поставить, желаемое время. Заявка идёт по этапам: «новая», «выезд назначен», «в работе», «ждём запчасть», «выполнена», «оплачена» или «отменена» с причиной. Диспетчер назначает мастера, видя загрузку всех мастеров на день. Мастер с телефона видит свои выезды, отмечает работы, расход фреона и запчастей, прикладывает фото и получает подпись клиента. С компаниями заключаем договоры сезонного обслуживания: система сама создаёт плановые выезды раз в квартал. Руководитель раз в неделю смотрит отчёт: выручка, выезды по мастерам, повторные вызовы по гарантии. Закупками запчастей занимается клиент, его телеграм клиент. На сайте — услуги, цены «от» и форма заявки."}</p>
      <ul>
        <li>{"Этапы заявки"}</li>
        <li>{"Назначение мастера по загрузке"}</li>
        <li>{"Отметка работ с фото"}</li>
        <li>{"Плановые выезды по договору"}</li>
        <li>{"Недельный отчёт"}</li>
      </ul>
      <p>{"Мастер видит только свои выезды"}</p>
      <p>{"Отмена требует причины"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
